@open_router.get("/", include_in_schema=False)
async def landing():
    return HTMLResponse(page(), headers={**SECURITY, "Cache-Control": "no-cache"})


@open_router.get("/public/{name}", include_in_schema=False)
async def public_asset(name: str):
    allowed = {"landing.css": "text/css; charset=utf-8", "landing.js": "text/javascript; charset=utf-8",
               "social-card.svg": "image/svg+xml", "service-map.svg": "image/svg+xml", "mark.svg": "image/svg+xml"}
    if name not in allowed:
        return Response(status_code=404)
    return FileResponse(STATIC / name, media_type=allowed[name], headers={
        **SECURITY, "Cache-Control": "public, max-age=3600",
    })


@open_router.get("/robots.txt", include_in_schema=False)
async def robots():
    return PlainTextResponse("User-agent: *\nAllow: /$\nDisallow: /panel/\nDisallow: /join/\nDisallow: /feedback\nDisallow: /health\nSitemap: https://bot-lpc.ru/sitemap.xml\n", headers=SECURITY)


@open_router.get("/sitemap.xml", include_in_schema=False)
async def sitemap():
    return Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>https://bot-lpc.ru/</loc></url></urlset>', media_type="application/xml", headers=SECURITY)
